from scipy.optimize import minimize_scalar
t=np.asarray(df['t'],float); P=np.asarray(df['P'],float); y=np.asarray(df['dP_dt'],float)
F={'1':np.ones_like(t),'t':t,'t2':t**2,'sqrt t':np.sqrt(t),'exp(-t)':np.exp(-t),'cos t':np.cos(t),'sin t':np.sin(t),'exp(t/4)':np.exp(t/4)}
G={'P':P,'P2':P**2,'P3':P**3,'1/P':1/P,'sqrtP':np.sqrt(P),'logP':np.log(P),'exp(-P)':np.exp(-P),'P*exp(-P)':P*np.exp(-P)}
prods={a+'*'+b:F[a]*G[b] for a in F for b in G}
names=list(prods)
def nm_for(w,n1,n2):
    A=np.column_stack([t,np.sin(w*t)/P,prods[n1],prods[n2]])
    c_=np.linalg.lstsq(A,y,rcond=None)[0]
    return np.mean((y-A@c_)**2)/np.var(y)
best=[]
for n1,n2 in itertools.combinations(names,2):
    ws=np.arange(0.05,1.5,0.03)
    vals=[nm_for(w,n1,n2) for w in ws]
    i=int(np.argmin(vals))
    best.append((vals[i],ws[i],n1,n2))
best.sort(key=lambda x:x[0])
out=[]
for v,w0,n1,n2 in best[:6]:
    r=minimize_scalar(lambda w: nm_for(w,n1,n2), bounds=(w0-0.03,w0+0.03), method='bounded')
    out.append((r.fun,r.x,n1,n2))
out.sort(key=lambda x:x[0])
for o in out: print(o)

